+
+        assertThat(mediaTypeParser.parseMediaType(mediaType + "; key = value"),
+            is(nullValue()));
+        assertThat(mediaTypeParser.parseMediaType(mediaType + "; key=") ,
+            is(nullValue()));
+    }
